def terms(x):
    u = x[:, 1:]
    (i, j) = np.triu_indices(u.shape[1], 1)
    return np.column_stack((u * u, u[:, i] * u[:, j], u / (1 + 0.25 * u * u)))

def _cell_weights(lab, stratum):
    (_, cell, count) = np.unique(np.column_stack((lab, stratum)), axis=0, return_inverse=True, return_counts=True)
    return len(lab) / (len(count) * count[cell.ravel()])

def _branches(split, dt, times, tau):
    tail = np.r_[np.cumsum(dt[:0:-1])[::-1], 0.0]
    kernel = -np.expm1(-dt[:, None] / tau) * np.exp(-tail[:, None] / tau)
    end = split['past_stress'] @ kernel + split['initial_memory_states'] * np.exp(-sum(dt) / tau)
    gap = split['stress_hold_0'][:, None] - end
    return (gap[:, None, :] * -np.expm1(-times[:, None] / tau), gap / tau)
